    /**
     * Render a pure vector Bootstrap Icon SVG
     *
     * @param string $name Bootstrap icon name (e.g. 'airplane-fill', 'person', 'envelope-fill')
     * @param int|string $size Size in pixels (default: 18)
     * @param string $color CSS fill color (default: 'currentColor')
     * @param string $extraClasses Optional CSS class names
     * @param string $style Optional inline style string
     * @return string
     */
    public static function render(string $name, int|string $size = 18, string $color = 'currentColor', string $extraClasses = '', string $style = ''): string
    {
        $normalizedName = self::normalizeIconName($name);
        $path = self::$icons[$normalizedName] ?? self::$icons['info-circle-fill'];
        
        $baseStyle = "display: inline-block; vertical-align: middle; line-height: 1;";
        if (!empty($style)) {
            $baseStyle .= ' ' . $style;
        }

        return sprintf(
            '<svg xmlns="http://www.w3.org/2000/svg" width="%s" height="%s" fill="%s" class="bi bi-%s %s" viewBox="0 0 16 16" style="%s">%s</svg>',
            htmlspecialchars((string)$size, ENT_QUOTES),
            htmlspecialchars((string)$size, ENT_QUOTES),
            htmlspecialchars($color, ENT_QUOTES),
            htmlspecialchars($normalizedName, ENT_QUOTES),
            htmlspecialchars(trim($extraClasses), ENT_QUOTES),
            htmlspecialchars($baseStyle, ENT_QUOTES),
            $path
        );
    }

    /**
     * Map common aliases or label words to official Bootstrap Icon names
     */
    public static function normalizeIconName(string $input): string
    {
        $key = strtolower(trim($input));
        $key = preg_replace('/^bi-/', '', $key);

        if (isset(self::$icons[$key])) {
            return $key;
        }

        $aliases = [
            'user'       => 'person-fill',
            'member'     => 'person-fill',
            'customer'   => 'person-fill',
            'driver'     => 'person-check-fill',
            'passenger'  => 'person-fill',
            'code'       => 'ticket-perforated-fill',
            'ticket'     => 'ticket-perforated-fill',
            'id'         => 'ticket-perforated-fill',
            'hash'       => 'ticket-perforated-fill',
            'booking'    => 'ticket-perforated-fill',
            'email'      => 'envelope-fill',
            'mail'       => 'envelope-fill',
            'phone'      => 'telephone-fill',
            'mobile'     => 'telephone-fill',
            'contact'    => 'telephone-fill',
            'location'   => 'geo-alt-fill',
            'city'       => 'geo-alt-fill',
            'pickup'     => 'geo-alt-fill',
            'drop'       => 'geo-alt-fill',
            'crown'      => 'award-fill',
            'tier'       => 'award-fill',
            'shield'     => 'shield-check',
            'safety'     => 'shield-check',
            'security'   => 'shield-check',
            'car'        => 'car-front-fill',
            'vehicle'    => 'car-front-fill',
            'fleet'      => 'car-front-fill',
            'clock'      => 'clock-history',
            'time'       => 'clock-history',
            'calendar'   => 'calendar-event',
            'date'       => 'calendar-event',
            'headset'    => 'headset',
            'support'    => 'headset',
            'concierge'  => 'headset',
            'gift'       => 'gift-fill',
            'perk'       => 'gift-fill',
            'privilege'  => 'gift-fill',
            'payment'    => 'credit-card-fill',
            'card'       => 'credit-card-fill',
            'fare'       => 'credit-card-fill',
            'amount'     => 'credit-card-fill',
            'check'      => 'check-circle-fill',
            'plane'      => 'airplane-fill',
            'flight'     => 'airplane-fill',
            'travel'     => 'airplane-fill',
            'stars'      => 'stars',
            'key'        => 'key-fill',
            'warning'    => 'exclamation-triangle-fill',
            'cancel'     => 'x-circle-fill',
        ];

        return $aliases[$key] ?? 'info-circle-fill';
    }
}
